            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xC34221E89C90B638ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x5E4207AB228641B9ULL) ^ aOUSaltG[((aIndex + 373U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x0DD7939A8CC5629FULL), 57U);
