            aOrbiterE = ((aWandererJ + RotL64(aPrevious, 29U)) + 0x29764663721B7BDFULL) + aOASaltA[(((511U - aIndex) + 487U)) & S_SALT1];
            aOrbiterI = ((aWandererE + RotL64(aCross, 43U)) + RotL64(aCarry, 47U)) + 0xB4F95B4F3308EB9FULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 35U)) + 0xC125A9443B1902C9ULL) + aOASaltB[((aIndex + 325U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aScatter, 53U)) + 0x4AB54FB02693A5FAULL;
            aOrbiterB = ((aWandererD + RotL64(aCross, 20U)) + 0xF07C738CB210411BULL) + aOASaltE[((aIndex + 412U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x1175AD14BD17C31FULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0xDAC5027C3BA7EF98ULL) ^ aOUSaltE[((aIndex + 94U)) & S_SALT1];
